{
  "aggregate_id": "DEF-NRS-484A-230::school_bus",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The vehicle definition excludes devices moved by human power, so the admitting motor-vehicle requirement reaches no member of this class."
    },
    {
      "class": "ru.bus",
      "verdict": "supported",
      "reason": "The bus contract does not establish or rule out the required passenger capacity, regular school transportation, ownership or compensation conditions."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "A child pedestrian is a person rather than a motor vehicle, so the admitting words do not reach this class."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "Commercial mass or licensing establishes neither the school-bus admission conditions nor the jurisdictional and operational conditions of the commercial-vehicle exception."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "Electric bicycles are expressly excluded from motor vehicles, which the school-bus definition requires."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "Electric scooters are expressly excluded from motor vehicles, which the school-bus definition requires."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "Emergency designation neither establishes nor rules out the capacity and school-transport conditions, and the posted words do not categorically exclude this class."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "supported",
      "reason": "The fire-fighting vehicle contract neither establishes nor rules out the capacity and school-transport conditions, and no categorical exception names it."
    },
    {
      "class": "ru.moped",
      "verdict": "underdetermined",
      "reason": "Neither the moped contract nor its posted definition precludes actual use to carry more than 10 passengers, while neither establishes the remaining admission conditions."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "The class contract does not establish the additional school-bus conditions, and the admitting words do not require qualifying members to bear school-bus markings."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "underdetermined",
      "reason": "The wheel and riding-position restrictions do not preclude actual use to carry more than 10 passengers, while the contract does not establish the remaining admission conditions."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "Official or contracted road service does not establish or rule out the required capacity, ownership or control, and regular school transportation."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "A pedestrian is a person rather than a motor vehicle, so the admitting words do not reach this class."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian rather than a motor vehicle, so the admitting words do not reach this class."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "supported",
      "reason": "The motor-vehicle definition expressly requires that the vehicle not be operated upon rails."
    },
    {
      "class": "ru.school_bus",
      "verdict": "underdetermined",
      "reason": "Designation and markings for carrying school children do not establish the specified capacity, regular operation, ownership or compensation conditions, or freedom from the exceptions."
    },
    {
      "class": "ru.taxicab",
      "verdict": "supported",
      "reason": "The class contract fixes neither passenger capacity nor the school-transport and contractual conditions needed to determine admission or application of the passenger-car exception."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "supported",
      "reason": "The contract establishes neither the school-transport admission conditions nor the regulatory jurisdiction and operation required by the carrier exception."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "supported",
      "reason": "Although a drawn vehicle does not satisfy self-propulsion, the contract also includes combinations whose satisfaction of the admission conditions is not determined."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "supported",
      "reason": "Public transit service does not determine whether the required school-transport conditions or the carrier exception apply."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "A goods-carrying body neither rules out actual use to carry more than 10 passengers nor establishes the remaining school-bus admission conditions."
    }
  ]
}

